// 文法速查表資料（草稿，待老師審核）。k = 西語搜尋用關鍵字（自動產生，不會顯示）
window.GRAMMAR={"books":{"1":"A1","2":"A2","3":"B1"},"lessons":{"1-1":"歡迎你來台灣！","1-2":"我的家人","1-3":"週末做什麼？","1-4":"請問一共多少錢？","1-5":"牛肉麵真好吃","1-6":"他們學校在山上","1-7":"早上九點去 KTV","1-8":"坐火車去台南","1-9":"放假去哪裡玩？","1-10":"台灣的水果很好吃","1-11":"我要租房子","1-12":"你在台灣學多久的中文？","1-13":"生日快樂","1-14":"天氣這麼冷！","1-15":"我很不舒服","2-1":"請問，到師到怎麼走？","2-2":"還是坐捷運吧！","2-3":"你的中文進步了！","2-4":"我打工，我教法文","2-5":"吃喜酒","2-6":"我打算搬到學校附近","2-7":"垃圾車來了！","2-8":"學功夫","2-9":"那個城市好漂亮","2-10":"歡迎到我家來包餃子","2-11":"台灣好玩的地方真多","2-12":"怎麼吃才健康？","2-13":"我的手機掉了","2-14":"我要開始工作了","2-15":"過春節","3-1":"開學了","3-2":"八折起","3-3":"外套帶了沒有？","3-4":"我愛台灣的人情味","3-5":"現在流行什麼？","3-6":"到鄉下住一晚！","3-7":"我最親的家「人」","3-8":"我想做自己","3-9":"網購時代","3-10":"我住院了","3-11":"台灣故事","3-12":"我要去投票"},"points":[{"id":"1-1-0","b":1,"l":1,"t":"Ways to Ask Questions in Chinese / Asking Questions with 嗎 ma","k":"pregunta preguntar interrogativa","es":"Para preguntas de sí/no: añade 嗎 al final de una oración afirmativa. También puedes usar la forma A-no-A (verbo + 不 + verbo).","ex":[["你是學生嗎？","¿Eres estudiante?"],["你是不是學生？","¿Eres o no eres estudiante?"]]},{"id":"1-1-1","b":1,"l":1,"t":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","k":"pregunta preguntar interrogativa negación negar negativa","es":"Se responde repitiendo el verbo: 是 / 不是. La negación 不 va justo antes del verbo o adjetivo. No se contesta con un simple «sí/no».","ex":[["你是老師嗎？——不是，我不是老師。","¿Eres profesor? — No, no soy profesor."]]},{"id":"1-1-2","b":1,"l":1,"t":"Modification Marker 很 hěn","k":"","es":"Con adjetivos (verbos estativos) se pone 很 antes del adjetivo. Aquí 很 casi no significa «muy»; sin él, la oración suena a comparación.","ex":[["我很忙。","Estoy ocupado."]]},{"id":"1-1-3","b":1,"l":1,"t":"Contrastive Questions with 呢 ne","k":"pregunta preguntar interrogativa","es":"呢 devuelve la misma pregunta al otro: «¿y tú?», «¿y …?».","ex":[["我很好，你呢？","Yo estoy bien, ¿y tú?"]]},{"id":"1-2-0","b":1,"l":2,"t":"的 de possessive","k":"","es":"Sustantivo/pronombre + 的 + sustantivo expresa posesión. Con familiares o personas muy cercanas se suele omitir 的.","ex":[["這是我的書。","Este es mi libro."],["我媽媽很忙。","Mi mamá está ocupada."]]},{"id":"1-2-1","b":1,"l":2,"t":"Modifier Marker 的 de","k":"","es":"的 une un modificador (adjetivo o frase) con el sustantivo que describe. El modificador siempre va delante del sustantivo.","ex":[["她是一個很好的老師。","Ella es una muy buena profesora."]]},{"id":"1-2-2","b":1,"l":2,"t":"有 yǒu possessive","k":"","es":"有 = tener. Su negación es 沒有 (nunca 不有).","ex":[["我有兩個姐姐，沒有哥哥。","Tengo dos hermanas mayores y ningún hermano mayor."]]},{"id":"1-2-3","b":1,"l":2,"t":"都 dōu totality","k":"","es":"都 = todos / ambos. Va antes del verbo y se refiere a lo que aparece antes de él.","ex":[["我們都是學生。","Todos somos estudiantes."]]},{"id":"1-2-4","b":1,"l":2,"t":"Measures 個 ge and 張 zhāng","k":"clasificador clasificadores medida contar cantidad","es":"Estructura: número + clasificador + sustantivo. 個 es el clasificador más general; 張 se usa para cosas planas (papel, mesa, boleto, foto).","ex":[["三個人、一張桌子","tres personas, una mesa"]]},{"id":"1-3-0","b":1,"l":3,"t":"Placement of Time Words","k":"tiempo momento orden secuencia lugar ubicación dónde existencia hay","es":"Las palabras de tiempo van antes del verbo (después del sujeto o al inicio de la oración), nunca al final.","ex":[["我明天去台北。","Mañana voy a Taipéi."]]},{"id":"1-3-1","b":1,"l":3,"t":"To Go Do Something with 去 qù","k":"dirección movimiento","es":"去 + lugar + verbo: ir a un lugar para hacer algo.","ex":[["我去圖書館看書。","Voy a la biblioteca a leer."]]},{"id":"1-3-2","b":1,"l":3,"t":"Topic Sentences","k":"","es":"Se puede poner primero el tema (algo ya conocido) y luego comentarlo. El objeto pasa al inicio de la oración.","ex":[["中文我會說，日文我不會說。","El chino sí sé hablarlo; el japonés no."]]},{"id":"1-3-3","b":1,"l":3,"t":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","k":"","es":"Los adverbios 也, 都 y 常 van después del sujeto y antes del verbo. Si aparecen 也 y 都 juntos, 也 va primero.","ex":[["我們也都喜歡吃麵。","A nosotros también nos gusta a todos comer fideos."]]},{"id":"1-3-4","b":1,"l":3,"t":"Making Suggestions 吧 ba","k":"sugerencia proposición","es":"吧 al final de la oración hace una sugerencia o invitación suave: «vamos a…», «¿qué tal si…?».","ex":[["我們去吃飯吧。","Vamos a comer."]]},{"id":"1-4-0","b":1,"l":4,"t":"Measures 塊 kuài, 杯 bēi,支 zhī and 種 zhǒng","k":"clasificador clasificadores medida contar cantidad","es":"塊 para dinero; 杯 para bebidas en vaso o taza; 支 para objetos largos y delgados (lápiz, bolígrafo); 種 = tipo, clase.","ex":[["一杯咖啡、兩支筆、三種水果、五十塊","una taza de café, dos bolígrafos, tres tipos de fruta, cincuenta dólares"]]},{"id":"1-4-1","b":1,"l":4,"t":"Preposition 幫 bāng on behalf of","k":"","es":"幫 + persona + verbo = hacer algo por alguien / en su lugar.","ex":[["我幫你買咖啡。","Te compro el café."]]},{"id":"1-4-2","b":1,"l":4,"t":"的 De-phrase with the Head Noun Omitted","k":"","es":"Cuando ya se sabe de qué sustantivo se habla, se omite y queda «modificador + 的»: «el/la/los de…».","ex":[["這杯是我的。","Esta taza es la mía."],["紅色的比較貴。","El rojo es más caro."]]},{"id":"1-4-3","b":1,"l":4,"t":"太…了 tài…le overly","k":"","es":"太 + adjetivo + 了 = demasiado… (a veces solo exclamación: «¡qué… !»).","ex":[["這個太貴了！","¡Esto es demasiado caro!"]]},{"id":"1-4-4","b":1,"l":4,"t":"能 néng capability","k":"poder saber habilidad capacidad permiso posibilidad","es":"能 expresa capacidad o posibilidad: «puedo», «es posible». Negación: 不能.","ex":[["你明天能來嗎？","¿Puedes venir mañana?"]]},{"id":"1-4-5","b":1,"l":4,"t":"多 duō …and more","k":"","es":"Después de un número, 多 significa «y pico, más de». También se usa en preguntas de grado: 多大, 多高, 多久.","ex":[["我有三十多本書。","Tengo más de treinta libros."]]},{"id":"1-5-0","b":1,"l":5,"t":"有一點 yǒu yìdiǎn slightly","k":"","es":"有一點 + adjetivo = un poco, algo. Suele expresar algo que no es del todo agradable.","ex":[["今天有一點冷。","Hoy hace un poco de frío."]]},{"id":"1-5-1","b":1,"l":5,"t":"Complement Marker 得 de","k":"complemento resultado potencial","es":"Verbo + 得 + adjetivo describe cómo se hace la acción. Si hay objeto, se repite el verbo.","ex":[["他跑得很快。","Corre muy rápido."],["他說中文說得很好。","Habla muy bien el chino."]]},{"id":"1-5-2","b":1,"l":5,"t":"Acquired Skills 會 huì","k":"poder saber habilidad capacidad permiso posibilidad","es":"會 = saber hacer algo (habilidad aprendida). Negación: 不會.","ex":[["我會說中文。","Sé hablar chino."]]},{"id":"1-5-3","b":1,"l":5,"t":"Destination Marker 到 dào","k":"","es":"Verbo de movimiento + 到 + lugar: llegar hasta / ir hasta. 到 marca el destino.","ex":[["他們開車到高雄。","Ellos van en coche hasta Kaohsiung."]]},{"id":"1-6-0","b":1,"l":6,"t":"Locative Marker 在 zài","k":"progresivo continuo estar haciendo presente lugar ubicación dónde existencia hay","es":"Sujeto + 在 + lugar indica dónde está algo o alguien (algo que ya se conoce).","ex":[["我的手機在桌子上。","Mi celular está sobre la mesa."]]},{"id":"1-6-1","b":1,"l":6,"t":"Existential Sentence with 有 yǒu","k":"lugar ubicación dónde existencia hay","es":"Lugar + 有 + cosa/persona = en ese lugar hay algo. Contraste: 在 (algo conocido está en…) vs. 有 (en un lugar hay algo).","ex":[["桌子上有一本書。","Sobre la mesa hay un libro."]]},{"id":"1-6-2","b":1,"l":6,"t":"Softened Action V（一）V","k":"","es":"Repetir el verbo (V一V / VV) suaviza la acción: «un poquito», «probar». Se usa con acciones cortas.","ex":[["你看(一)看。","Echa un vistazo."],["讓我想一想。","Déjame pensarlo un momento."]]},{"id":"1-6-3","b":1,"l":6,"t":"不是 búshì Negation","k":"negación negar negativa","es":"不是 niega 是 y sirve para corregir: «no es X (sino Y)». Se usa para negar sustantivos.","ex":[["我不是老師，我是學生。","No soy profesor, soy estudiante."]]},{"id":"1-6-4","b":1,"l":6,"t":"Location of an Activity","k":"lugar ubicación dónde existencia hay","es":"El lugar donde ocurre la actividad va con 在 antes del verbo: 在 + lugar + verbo.","ex":[["我在家看書。","Leo en casa."]]},{"id":"1-7-0","b":1,"l":7,"t":"Time and Place of Events","k":"tiempo momento orden secuencia lugar ubicación dónde existencia hay","es":"Orden básico: sujeto + tiempo + lugar + verbo.","ex":[["我昨天在家看電影。","Ayer vi una película en casa."]]},{"id":"1-7-1","b":1,"l":7,"t":"從 cóng…到 dào… from A to B","k":"lugar ubicación dónde existencia hay","es":"從 A 到 B = de A a B (para lugares o tiempos).","ex":[["從台北到高雄","de Taipéi a Kaohsiung"],["我從九點到十二點上課。","Tengo clase de nueve a doce."]]},{"id":"1-7-2","b":1,"l":7,"t":"Progressive, On-going Actions 在 zài","k":"progresivo continuo estar haciendo presente","es":"(正)在 + verbo = estar haciendo algo (acción en curso). Puede terminar con 呢.","ex":[["我在吃飯。","Estoy comiendo."]]},{"id":"1-7-3","b":1,"l":7,"t":"每 měi each and every","k":"siempre nunca frecuencia","es":"每 + clasificador / palabra de tiempo = cada, todos los. Suele ir con 都 antes del verbo.","ex":[["我每天都喝咖啡。","Tomo café todos los días."]]},{"id":"1-7-4","b":1,"l":7,"t":"可以 kěyǐ permission","k":"poder saber habilidad capacidad permiso posibilidad","es":"可以 = permiso: «se puede / puedo». Para pedir permiso: 可以…嗎？ Prohibición: 不可以.","ex":[["這裡可以拍照嗎？","¿Se pueden tomar fotos aquí?"]]},{"id":"1-8-0","b":1,"l":8,"t":"Companionship with 跟 gēn","k":"","es":"A 跟 B 一起 + verbo = hacer algo con B.","ex":[["我跟朋友一起去看電影。","Voy al cine con mis amigos."]]},{"id":"1-8-1","b":1,"l":8,"t":"Asking How with 怎麼 zěnme","k":"pregunta preguntar interrogativa","es":"怎麼 + verbo pregunta por la manera o el método de hacer algo.","ex":[["這個字怎麼念？","¿Cómo se pronuncia este carácter?"],["去台北車站怎麼走？","¿Cómo se va a la estación de Taipéi?"]]},{"id":"1-8-2","b":1,"l":8,"t":"Implicit Comparison with 比較 bǐjiào","k":"comparar comparación comparativo más menos igual semejante","es":"比較 + adjetivo/verbo = «más» o «relativamente»; es una comparación implícita, sin decir con qué se compara.","ex":[["我比較喜歡喝茶。","Prefiero tomar té."]]},{"id":"1-8-3","b":1,"l":8,"t":"又 yòu…又 yòu…… both A and B","k":"","es":"又 A 又 B = a la vez A y B (dos cualidades juntas).","ex":[["這家的菜又好吃又便宜。","La comida de este lugar es rica y barata."]]},{"id":"1-8-4","b":1,"l":8,"t":"Comparison with 比 bǐ","k":"comparar comparación comparativo más menos igual semejante","es":"A 比 B + adjetivo = A es más… que B. Con 比 no se usa 很. Para indicar la diferencia: 一點 / 多了 / 三歲, etc.","ex":[["哥哥比我高。","Mi hermano mayor es más alto que yo."],["他比我大三歲。","Es tres años mayor que yo."]]},{"id":"1-9-0","b":1,"l":9,"t":"Time-When vs. Time-Duration","k":"tiempo momento orden secuencia","es":"El momento (cuándo) va antes del verbo; la duración (cuánto tiempo) va después del verbo.","ex":[["我八點上課。","Tengo clase a las ocho."],["我每天睡八個小時。","Duermo ocho horas al día."]]},{"id":"1-9-1","b":1,"l":9,"t":"Time-Duration ‘for a period of time’","k":"tiempo momento orden secuencia","es":"Verbo + duración (+ 的 + objeto) indica cuánto tiempo dura la acción.","ex":[["我想在台灣住三個月。","Quiero vivir tres meses en Taiwán."]]},{"id":"1-9-2","b":1,"l":9,"t":"…的時候 de shíhòu when","k":"tiempo momento orden secuencia","es":"Frase + 的時候 = cuando… (en el momento en que ocurre algo).","ex":[["我吃飯的時候不看手機。","Cuando como no miro el celular."]]},{"id":"1-9-3","b":1,"l":9,"t":"有時候 yǒu shíhòu…有時候 yǒu shíhòu… sometimes … sometimes …","k":"tiempo momento orden secuencia","es":"有時候 A，有時候 B = a veces A, a veces B.","ex":[["我有時候喝茶，有時候喝咖啡。","A veces tomo té y a veces café."]]},{"id":"1-9-4","b":1,"l":9,"t":"Condition and Consequence with 要是 yaoshi…就 jiu…","k":"tiempo momento orden secuencia condicional condición si causa razón porque consecuencia resultado","es":"要是 + condición，就 + resultado = si…, entonces…. 就 va antes del verbo.","ex":[["要是下雨，我就不去。","Si llueve, no voy."]]},{"id":"1-10-0","b":1,"l":10,"t":"V V 看 kàn to try and see","k":"","es":"Verbo repetido + 看 = probar a hacer algo para ver qué tal.","ex":[["這個很好吃，你吃吃看。","Esto está muy rico, pruébalo."]]},{"id":"1-10-1","b":1,"l":10,"t":"Intensification with Reduplicated State Verbs","k":"reduplicación repetición","es":"Duplicar un adjetivo (AA) lo hace más vívido; ya no se le pone 很. Para adjetivos de dos sílabas se usa AABB.","ex":[["她的眼睛大大的。","Tiene los ojos bien grandes."]]},{"id":"1-10-2","b":1,"l":10,"t":"Clause as Modifiers of Nouns","k":"","es":"Una frase u oración + 的 + sustantivo: la descripción siempre va antes del sustantivo (como una cláusula de relativo).","ex":[["我喜歡的老師很年輕。","El profesor que me gusta es muy joven."]]},{"id":"1-10-3","b":1,"l":10,"t":"Change in Situation with Sentential 了 le","k":"","es":"了 al final de la oración indica un cambio de situación o un estado nuevo: «ya», «ahora ya».","ex":[["我現在不累了。","Ya no estoy cansado."],["天黑了。","Ya oscureció."]]},{"id":"1-10-4","b":1,"l":10,"t":"Cause and Effect with 因為 yīnwèi，所以 suǒyǐ","k":"causa razón porque consecuencia resultado","es":"因為 introduce la causa y 所以 el resultado. En chino se suelen usar juntos.","ex":[["因為下雨，所以我不去。","Como llueve, no voy."]]},{"id":"1-11-0","b":1,"l":11,"t":"To Come to Do Something with 來 lái","k":"dirección movimiento","es":"來 + verbo = venir a hacer algo (desde el punto de vista del lugar donde se habla).","ex":[["他來台灣學中文。","Él viene a Taiwán a estudiar chino."]]},{"id":"1-11-1","b":1,"l":11,"t":"Sooner Than Expected with 就 jiù","k":"tiempo momento orden secuencia","es":"Tiempo + 就 + verbo = la acción ocurre más temprano o más rápido de lo esperado.","ex":[["我六點就起床了。","Me levanté ya a las seis."]]},{"id":"1-11-2","b":1,"l":11,"t":"Existential Subject with 有 yǒu","k":"lugar ubicación dónde existencia hay","es":"有 + sujeto indefinido al inicio: «hay alguien/algo que…».","ex":[["有人找你。","Alguien te busca."]]},{"id":"1-11-3","b":1,"l":11,"t":"Different Types of 會 huì","k":"poder saber habilidad capacidad permiso posibilidad","es":"會 también expresa probabilidad o futuro: «seguramente», «va a». No solo significa «saber hacer».","ex":[["明天會下雨。","Mañana va a llover."],["他會來嗎？","¿Vendrá él?"]]},{"id":"1-11-4","b":1,"l":11,"t":"Omitting Nouns at 2nd mention","k":"","es":"Cuando el sustantivo ya se mencionó, la segunda vez se puede omitir.","ex":[["這件太大了，有小的嗎？","Esta es demasiado grande, ¿tiene una más pequeña?"]]},{"id":"1-12-0","b":1,"l":12,"t":"先 xiān…再 zài… first…, and then …","k":"tiempo momento orden secuencia","es":"先 A，再 B = primero A, luego B.","ex":[["我們先吃飯，再看電影。","Primero comemos y luego vemos una película."]]},{"id":"1-12-1","b":1,"l":12,"t":"To Focus with 是 shì…的 de…","k":"","es":"是…的 destaca el cuándo, dónde, cómo o con quién de una acción que ya ocurrió.","ex":[["我是昨天來的。","Vine ayer."],["我是坐高鐵來的。","Vine en el tren de alta velocidad."]]},{"id":"1-12-2","b":1,"l":12,"t":"以後 yǐhòu after…","k":"tiempo momento orden secuencia","es":"Tiempo / frase + 以後 = después de…. Solo, 以後 significa «en el futuro».","ex":[["下課以後，我去吃飯。","Después de clase voy a comer."]]},{"id":"1-12-3","b":1,"l":12,"t":"Special Meanings of 好 hǎo/難 nán +Verbs","k":"","es":"好 + verbo = fácil / agradable de…: 好吃, 好看, 好用. 難 + verbo = difícil / desagradable de…: 難吃, 難看, 難用.","ex":[["這個手機很好用。","Este celular es muy fácil de usar."],["這道菜很難吃。","Este platillo sabe mal."]]},{"id":"1-13-0","b":1,"l":13,"t":"一 yī…就 jiù… …as soon as…","k":"tiempo momento orden secuencia","es":"一 A 就 B = en cuanto A, B.","ex":[["他一下課就回家。","En cuanto termina la clase, se va a casa."]]},{"id":"1-13-1","b":1,"l":13,"t":"Completed Action with Verbal 了 le","k":"pasado completado terminado","es":"Verbo + 了 indica que la acción se completó (no equivale a «pasado»). Suele haber una cantidad o complemento después.","ex":[["我買了一本書。","Compré un libro."]]},{"id":"1-13-2","b":1,"l":13,"t":"不 Negation vs.沒 Negation","k":"negación negar negativa","es":"不 niega hábitos, presente, futuro y voluntad. 沒(有) niega que una acción haya ocurrido, y niega 有. Con 沒 no se usa 了.","ex":[["我不喝咖啡。","No tomo café."],["我昨天沒去學校。","Ayer no fui a la escuela."]]},{"id":"1-13-3","b":1,"l":13,"t":"All-inclusive with Question Words","k":"pregunta preguntar interrogativa","es":"Pregunta + 都 / 也: «cualquiera, todo, nadie…». Con negación: 誰都不 / 什麼都沒.","ex":[["誰都知道。","Todo el mundo lo sabe."],["我什麼都吃。","Como de todo."]]},{"id":"1-13-4","b":1,"l":13,"t":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","k":"","es":"多 / 少 + verbo + cantidad = más / menos de lo planeado (acción ya realizada).","ex":[["我多買了兩個。","Compré dos de más."]]},{"id":"1-13-5","b":1,"l":13,"t":"是不是 shìbú shì is it true?","k":"pregunta preguntar interrogativa negación negar negativa","es":"是不是 sirve para confirmar algo que se supone: «¿verdad que…?». Va antes del verbo o al final de la oración.","ex":[["你是不是累了？","¿Estás cansado, verdad?"]]},{"id":"1-13-6","b":1,"l":13,"t":"Comparison with 跟 gēn…一樣 yíyàng","k":"comparar comparación comparativo más menos igual semejante","es":"A 跟 B 一樣 (+ adjetivo) = A es igual que B.","ex":[["我的手機跟你的一樣。","Mi celular es igual al tuyo."],["我跟他一樣高。","Soy tan alto como él."]]},{"id":"1-14-0","b":1,"l":14,"t":"Time-Duration after Verbal 了 le","k":"tiempo momento orden secuencia pasado completado terminado","es":"Verbo + 了 + duración (+ 的 + objeto) = cuánto tiempo duró una acción ya terminada.","ex":[["我昨天睡了八個小時。","Ayer dormí ocho horas."]]},{"id":"1-14-1","b":1,"l":14,"t":"Completion-to-date with Double 了 le","k":"pasado completado terminado","es":"Verbo + 了 + cantidad + 了 = la acción lleva esa cantidad hasta ahora y todavía continúa.","ex":[["我學中文學了兩年了。","Llevo dos años estudiando chino."]]},{"id":"1-14-2","b":1,"l":14,"t":"快 kuài…了 le about to","k":"","es":"快 + verbo / adjetivo / hora + 了 = a punto de, ya casi.","ex":[["快下雨了。","Ya casi llueve."],["快十二點了。","Ya casi son las doce."]]},{"id":"1-14-3","b":1,"l":14,"t":"Comparison 更 gèng even more so","k":"comparar comparación comparativo más menos igual semejante","es":"更 + adjetivo = todavía más. Se compara con algo ya mencionado.","ex":[["這家比那家更好吃。","Este lugar es todavía más rico que aquel."]]},{"id":"1-14-4","b":1,"l":14,"t":"Inferior Comparison 沒有 méiyǒu…","k":"comparar comparación comparativo más menos igual semejante negación negar negativa","es":"A 沒有 B (那麼) + adjetivo = A no es tan… como B.","ex":[["我沒有哥哥那麼高。","No soy tan alto como mi hermano."]]},{"id":"1-15-0","b":1,"l":15,"t":"Non-committal Stance with Question Words","k":"pregunta preguntar interrogativa","es":"Con pronombres interrogativos se expresa «lo que quieras»: 什麼…就 + verbo. Es una postura sin compromiso.","ex":[["你想喝什麼就點什麼。","Pide lo que quieras beber."]]},{"id":"1-15-1","b":1,"l":15,"t":"To Dispose of Something with 把 bǎ","k":"disposición objeto complemento","es":"把 + objeto (ya conocido) + verbo + complemento: se «dispone» del objeto y se dice qué se hace con él. El verbo no puede ir solo.","ex":[["請你把窗戶打開。","Por favor abre la ventana."]]},{"id":"1-15-2","b":1,"l":15,"t":"V 了 le…就 jiù… do…right after doing…","k":"tiempo momento orden secuencia","es":"V 了 A 就 B = en cuanto terminé A, hago B.","ex":[["我下了課就回家。","En cuanto termine la clase me voy a casa."]]},{"id":"1-15-3","b":1,"l":15,"t":"一點 yìdiǎn a bit","k":"","es":"Adjetivo + 一點 = un poco más (suaviza una petición). Verbo + 一點 = un poco de.","ex":[["這個便宜一點好嗎？","¿Podría ser un poco más barato?"],["你多吃一點。","Come un poco más."]]},{"id":"1-15-4","b":1,"l":15,"t":"Comparing Actions with a 得 de Complement","k":"comparar comparación comparativo más menos igual semejante complemento resultado potencial","es":"Para comparar acciones con 得: A + verbo + 得 + 比 B + adjetivo, o A 比 B + verbo + 得 + adjetivo.","ex":[["他比我跑得快。","Corre más rápido que yo."]]},{"id":"1-15-5","b":1,"l":15,"t":"Complements of Degree in Comparison Structures","k":"comparar comparación comparativo más menos igual semejante complemento resultado potencial","es":"En la comparación con complemento de grado se puede añadir la diferencia: 一點 (un poco) o 多了 / 得多 (mucho más).","ex":[["他說得比我好多了。","Habla mucho mejor que yo."]]},{"id":"1-15-6","b":1,"l":15,"t":"Separable Verbs","k":"","es":"Los verbos separables (吃飯, 睡覺, 游泳, 見面) son verbo + objeto: se pueden separar y la duración o cantidad va en medio. No llevan otro objeto directo.","ex":[["我們見了三次面。","Nos vimos tres veces."],["他游了一個小時的泳。","Nadó una hora."]]},{"id":"2-1-0","b":2,"l":1,"t":"從 cóng…往 wǎng… go…from…","k":"lugar ubicación dónde existencia hay","es":"從 + lugar + 往 + dirección + verbo: desde… hacia… (se usa mucho para dar indicaciones).","ex":[["從這裡往前走，再往右轉。","Desde aquí sigue derecho y luego gira a la derecha."]]},{"id":"2-1-1","b":2,"l":1,"t":"Judgmental V-起來 qǐlái It’s my assessment that…","k":"dirección movimiento","es":"V + 起來 expresa una evaluación subjetiva: «a juzgar por cómo se ve / se oye / sabe / se siente».","ex":[["這個菜看起來很好吃。","Este platillo se ve muy rico."]]},{"id":"2-1-2","b":2,"l":1,"t":"Ongoing Action with -著 zhe","k":"progresivo continuo estar haciendo presente","es":"V + 著 indica un estado que continúa (resultado de una acción que permanece). Negación: 沒 + V + 著.","ex":[["門開著。","La puerta está abierta."],["他穿著一件藍色的外套。","Lleva puesta una chaqueta azul."]]},{"id":"2-1-3","b":2,"l":1,"t":"Two Simultaneously Actions with 一邊 yìbiān…一邊 yìbiān…","k":"","es":"一邊 A 一邊 B = hacer A y B al mismo tiempo (el mismo sujeto).","ex":[["他一邊走路一邊聽音樂。","Camina mientras escucha música."]]},{"id":"2-1-4","b":2,"l":1,"t":"Distance from with 離 lí…","k":"lugar ubicación dónde existencia hay","es":"A 離 B + (很) 遠 / 近 = A está lejos / cerca de B. 離 indica distancia; 從 indica punto de partida.","ex":[["我家離學校很近。","Mi casa está muy cerca de la escuela."]]},{"id":"2-2-0","b":2,"l":2,"t":"Emphatic Negation with 一點也不 yìdiǎn yě bù V …","k":"negación negar negativa énfasis enfático incluso","es":"一點也不 / 一點也沒 + verbo o adjetivo = en absoluto, nada. Es una negación enfática.","ex":[["我一點也不累。","No estoy nada cansado."]]},{"id":"2-2-1","b":2,"l":2,"t":"還是 háishì…吧 ba！ It would be better if …","k":"además adición también sugerencia proposición","es":"還是 + sugerencia + 吧 = mejor + (hagamos algo). Se compara y se recomienda una opción.","ex":[["太晚了，我們還是搭計程車吧。","Es muy tarde, mejor tomemos un taxi."]]},{"id":"2-2-2","b":2,"l":2,"t":"Form Adverbials with 一點 yìdiǎn","k":"","es":"Adjetivo + 一點 + verbo (o verbo + adjetivo + 一點) forma una petición suave: «hazlo un poco más…».","ex":[["請你說慢一點。","Por favor habla un poco más despacio."],["你早一點來。","Llega un poco más temprano."]]},{"id":"2-2-3","b":2,"l":2,"t":"Reduplication of Disyllabic Adjectives","k":"reduplicación repetición","es":"Los adjetivos de dos sílabas AB se duplican como AABB; resultan más vívidos y ya no llevan 很.","ex":[["房間乾乾淨淨的。","El cuarto está muy limpio."]]},{"id":"2-2-4","b":2,"l":2,"t":"不太 bútài not very","k":"negación negar negativa","es":"不太 + adjetivo / verbo = no muy, no demasiado. Es una negación suave.","ex":[["我不太喜歡吃辣。","No me gusta mucho el picante."]]},{"id":"2-2-5","b":2,"l":2,"t":"Locations with 部 bù /邊 biān","k":"lugar ubicación dónde existencia hay","es":"部 se usa para regiones (北部, 南部, 東部, 西部); 邊 para posiciones (上邊, 裡邊, 旁邊, 左邊, 右邊).","ex":[["台北在台灣的北部。","Taipéi está en el norte de Taiwán."],["銀行在郵局的旁邊。","El banco está al lado del correo."]]},{"id":"2-3-0","b":2,"l":3,"t":"Various Functions of 差不 chàbùduō","k":"negación negar negativa","es":"差不多 puede ser adjetivo («casi igual»), adverbio («casi») o «más o menos».","ex":[["我們差不多高。","Somos casi igual de altos."],["差不多十二點了。","Son casi las doce."]]},{"id":"2-3-1","b":2,"l":3,"t":"Experience Particle 過 guò","k":"experiencia alguna vez haber","es":"V + 過 indica experiencia: «alguna vez». Negación: 沒 + V + 過.","ex":[["我去過日本。","He ido a Japón."],["我沒吃過臭豆腐。","Nunca he comido tofu apestoso."]]},{"id":"2-3-2","b":2,"l":3,"t":"才 cái merely, only","k":"tiempo momento orden secuencia","es":"才 + cantidad pequeña = apenas, solo.","ex":[["現在才八點。","Apenas son las ocho."],["我才學了三個月。","Solo llevo tres meses estudiando."]]},{"id":"2-3-3","b":2,"l":3,"t":"想起來 xiǎngqǐlái to have remembered","k":"dirección movimiento","es":"想起來 = recordar de repente algo que se había olvidado.","ex":[["我想起來了，他叫王明。","Ya recordé, se llama Wang Ming."]]},{"id":"2-3-4","b":2,"l":3,"t":"Longer/Later Than Expected with 才 cái","k":"tiempo momento orden secuencia","es":"Tiempo + 才 + verbo = más tarde de lo esperado. Contrasta con 就 (más temprano de lo esperado).","ex":[["他十點才起床。","Se levanta hasta las diez."]]},{"id":"2-3-5","b":2,"l":3,"t":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","k":"reduplicación repetición","es":"Los verbos de dos sílabas AB duplicados como ABAB suavizan la acción: «un poco, para ver».","ex":[["我們討論討論吧。","Hablemos un poco de esto."]]},{"id":"2-4-0","b":2,"l":4,"t":"除了 chúle…，還 hái… in addition to…","k":"además adición también","es":"除了 A，還 B = además de A, también B.","ex":[["除了英文，他還會說中文。","Además de inglés, también habla chino."]]},{"id":"2-4-1","b":2,"l":4,"t":"按照…ànzhào… in accordance with","k":"","es":"按照 + norma / plan / indicación = según, conforme a.","ex":[["請按照老師說的做。","Por favor haz lo que dijo el profesor."]]},{"id":"2-4-2","b":2,"l":4,"t":"Various Meaning of the Preposition 跟 gēn","k":"","es":"跟 tiene varios usos: «con» (compañía), «de» en 跟…學 / 跟…借, «igual que» en 跟…一樣, y «y» entre sustantivos.","ex":[["我跟老師學中文。","Aprendo chino con el profesor."]]},{"id":"2-4-3","b":2,"l":4,"t":"Various Meanings of 給 gěi","k":"","es":"給 puede ser verbo («dar»), preposición («para») o marcar al destinatario después del verbo (寄給你).","ex":[["我給你一個禮物。","Te doy un regalo."],["我寄給他一封信。","Le envié una carta."]]},{"id":"2-4-4","b":2,"l":4,"t":"對 duì… towards…","k":"","es":"對 + persona / cosa + adjetivo o verbo = hacia, con respecto a. Es común en 對…有興趣 y 對…很好.","ex":[["我對台灣文化很有興趣。","Me interesa mucho la cultura de Taiwán."]]},{"id":"2-5-0","b":2,"l":5,"t":"還 hái still","k":"además adición también","es":"還 = todavía, aún (continúa una situación). 還沒 + verbo = todavía no.","ex":[["他還在睡覺。","Todavía está durmiendo."],["我還沒吃飯。","Todavía no he comido."]]},{"id":"2-5-1","b":2,"l":5,"t":"Manner of an Action with V 著 zhe","k":"progresivo continuo estar haciendo presente","es":"V1 + 著 + V2: V1 describe la manera en que se realiza V2.","ex":[["他笑著說話。","Habla sonriendo."]]},{"id":"2-5-2","b":2,"l":5,"t":"Multiple Verb Phrases in a Sentence","k":"","es":"En una oración se pueden encadenar varios verbos en el orden en que ocurren.","ex":[["她下班回家做飯。","Ella sale del trabajo, vuelve a casa y cocina."]]},{"id":"2-5-3","b":2,"l":5,"t":"When A Comes, Then B…with 等 děng 就…jiù…","k":"tiempo momento orden secuencia","es":"等 A 就 B = cuando ocurra A, entonces B.","ex":[["等你來了，我們就出發。","Cuando llegues, salimos."]]},{"id":"2-5-4","b":2,"l":5,"t":"While Doing A, B Happens with V 著 zhe V 著 zhe， 就 jiù…了 le","k":"tiempo momento orden secuencia progresivo continuo estar haciendo presente","es":"V著V著就…了 = mientras hacía algo, de pronto ocurrió otra cosa.","ex":[["他看著看著就睡著了。","Mientras miraba, se quedó dormido."]]},{"id":"2-6-0","b":2,"l":6,"t":"Destination Marker 到 dào","k":"","es":"V + 到 + lugar: la acción llega hasta ese lugar. 到 marca el destino.","ex":[["我們走到公園吧。","Caminemos hasta el parque."]]},{"id":"2-6-1","b":2,"l":6,"t":"Indirect Object Marker 給 gěi","k":"","es":"V + 給 + persona: dar o transferir algo a alguien (送給, 寄給, 交給, 借給).","ex":[["他送給我一本書。","Me regaló un libro."]]},{"id":"2-6-2","b":2,"l":6,"t":"Resultant Location with V+在 zài…","k":"progresivo continuo estar haciendo presente lugar ubicación dónde existencia hay","es":"V + 在 + lugar: como resultado de la acción, algo o alguien queda en ese lugar.","ex":[["我把車停在學校。","Estaciono el coche en la escuela."]]},{"id":"2-6-3","b":2,"l":6,"t":"Moving an Object to a Location with 把 bǎ","k":"lugar ubicación dónde existencia hay disposición objeto complemento","es":"把 + objeto + V + 到 / 在 / 給 + lugar o persona: mover un objeto a otro lugar.","ex":[["請把書放在桌子上。","Por favor pon el libro sobre la mesa."]]},{"id":"2-6-4","b":2,"l":6,"t":"而且 érqiě furthermore","k":"además adición también","es":"而且 = además. Añade información que refuerza lo anterior.","ex":[["這家餐廳很好吃，而且很便宜。","Este restaurante es rico y además barato."]]},{"id":"2-7-0","b":2,"l":7,"t":"Directional ConstructionsV1V2 and V1V2V3","k":"dirección movimiento","es":"Verbo + dirección (上, 下, 進, 出, 回, 過, 起) + 來 / 去: movimiento hacia (來) o lejos (去) del hablante. También V1V2V3.","ex":[["他走進來了。","Entró caminando."],["她跑出去了。","Salió corriendo."]]},{"id":"2-7-1","b":2,"l":7,"t":"把 bǎ with V1V2V3","k":"disposición objeto complemento","es":"把 + objeto + verbo + dirección + 來 / 去: mover el objeto en esa dirección.","ex":[["請把椅子搬到樓上去。","Por favor lleva la silla al piso de arriba."]]},{"id":"2-7-2","b":2,"l":7,"t":"Confrontation with 嗎?","k":"pregunta preguntar interrogativa","es":"Una pregunta con 嗎 puede expresar reproche o confrontación: «¿no ves que…?».","ex":[["你沒看到我在忙嗎？","¿No ves que estoy ocupado?"]]},{"id":"2-7-3","b":2,"l":7,"t":"Existential Sentence with Posture Verbs","k":"lugar ubicación dónde existencia hay","es":"Lugar + verbo de posición (坐, 站, 躺, 放, 掛, 貼) + 著 + persona o cosa: así está colocado.","ex":[["桌子上放著一本書。","Sobre la mesa hay un libro (puesto)."]]},{"id":"2-7-4","b":2,"l":7,"t":"為了 wèile in order to","k":"causa razón porque consecuencia resultado","es":"為了 + objetivo, + acción = para, con el fin de.","ex":[["為了學好中文，我每天聽廣播。","Para aprender bien chino escucho la radio todos los días."]]},{"id":"2-8-0","b":2,"l":8,"t":"見 jiàn as a Perceptual Result","k":"","es":"V + 見 expresa que la percepción se logró: 看見 (ver), 聽見 (oír).","ex":[["我聽見有人在叫我。","Oí que alguien me llamaba."]]},{"id":"2-8-1","b":2,"l":8,"t":"懂 dǒng as a Cognitive Result","k":"","es":"V + 懂 = comprender lo que se escucha o lee: 聽懂, 看懂.","ex":[["老師說的話我聽得懂。","Entiendo lo que dice el profesor."]]},{"id":"2-8-2","b":2,"l":8,"t":"會 huìas an Achievement Result","k":"poder saber habilidad capacidad permiso posibilidad","es":"V + 會 = aprender a hacer algo (logro): 學會, 教會.","ex":[["我學會了做蛋糕。","Aprendí a hacer pasteles."]]},{"id":"2-8-3","b":2,"l":8,"t":"Potential Capability with -得 de- or -不 bù-","k":"negación negar negativa complemento resultado potencial poder saber habilidad capacidad permiso posibilidad","es":"V + 得 + complemento = se puede; V + 不 + complemento = no se puede (por las circunstancias).","ex":[["我看得懂，他看不懂。","Yo sí lo entiendo al leerlo; él no."],["這麼多菜，我吃不完。","Con tanta comida, no puedo terminarla."]]},{"id":"2-8-4","b":2,"l":8,"t":"Capability Complement 了 liǎo","k":"complemento resultado potencial poder saber habilidad capacidad permiso posibilidad","es":"V + 得了 / 不了 = poder / no poder completar o soportar algo. Aquí 了 se lee liǎo.","ex":[["太多了，我吃不了。","Es demasiado, no puedo con todo."]]},{"id":"2-8-5","b":2,"l":8,"t":"Vs +得 de + complement so …that…","k":"complemento resultado potencial","es":"Adjetivo / verbo + 得 + resultado = tan… que…","ex":[["他高興得跳起來。","Estaba tan contento que saltó."]]},{"id":"2-8-6","b":2,"l":8,"t":"To Keep on Doing Something with 下去 xiàqù","k":"dirección movimiento","es":"V + 下去 = seguir haciendo algo (de ahora en adelante).","ex":[["你說下去，我在聽。","Sigue, te estoy escuchando."]]},{"id":"2-8-7","b":2,"l":8,"t":"Completion of an Action with V+完 wán","k":"pasado completado terminado","es":"V + 完 = terminar de hacer algo. Negación: 沒 + V + 完.","ex":[["我寫完功課了。","Terminé la tarea."]]},{"id":"2-9-0","b":2,"l":9,"t":"All Set and Ready with Verb Complement 好 hǎo","k":"complemento resultado potencial","es":"V + 好 = quedar listo o hecho bien: 準備好, 做好, 洗好.","ex":[["飯做好了。","La comida ya está lista."]]},{"id":"2-9-1","b":2,"l":9,"t":"To Be Successful in …with Verb Complement 到 dào","k":"complemento resultado potencial","es":"V + 到 = lograr el resultado esperado: 買到, 找到, 看到.","ex":[["我買到票了。","Conseguí el boleto."]]},{"id":"2-9-2","b":2,"l":9,"t":"Comparison with 比起來 bǐ qǐlái","k":"comparar comparación comparativo más menos igual semejante dirección movimiento","es":"跟 B 比起來，A… / 比起 B，A… = en comparación con B, A…","ex":[["跟台北比起來，高雄比較熱。","Comparado con Taipéi, Kaohsiung es más caluroso."]]},{"id":"2-9-3","b":2,"l":9,"t":"像 xiàng…一樣 yí yàng … is just like…","k":"comparar comparación comparativo más menos igual semejante","es":"A 像 B 一樣 (+ adjetivo / verbo) = A es como B.","ex":[["他像小孩子一樣愛玩。","Le gusta jugar como a un niño."]]},{"id":"2-9-4","b":2,"l":9,"t":"Adverbial Complements 極了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","k":"negación negar negativa complemento resultado potencial","es":"Adjetivo + 極了 / 得不得了 / 得很 = extremadamente. Van después del adjetivo.","ex":[["今天熱極了。","Hoy hace muchísimo calor."],["她高興得不得了。","Está contentísima."]]},{"id":"2-9-5","b":2,"l":9,"t":"Verb Complement 起 qǐ to be able to afford","k":"complemento resultado potencial","es":"V + 得起 / 不起 = poder / no poder permitirse algo (por dinero o categoría).","ex":[["這個包包太貴了，我買不起。","Esta bolsa es muy cara, no me la puedo permitir."]]},{"id":"2-10-0","b":2,"l":10,"t":"To Figure out with the Complement 出來 chūlái","k":"dirección movimiento complemento resultado potencial","es":"V + 出來 = descubrir, distinguir o llegar a darse cuenta (sacar a la luz).","ex":[["你聽得出來他是誰嗎？","¿Puedes reconocer quién es por la voz?"]]},{"id":"2-10-1","b":2,"l":10,"t":"Enough Space to Accommodate with Verb Complement 下 xià","k":"complemento resultado potencial","es":"V + 得下 / 不下 = hay / no hay espacio suficiente para acomodar algo.","ex":[["這個房間坐得下十個人。","En este cuarto caben diez personas sentadas."]]},{"id":"2-10-2","b":2,"l":10,"t":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","k":"disposición objeto complemento reduplicación repetición","es":"把 + objeto + V(一)V = hacer algo con el objeto de forma breve o ligera.","ex":[["請你把房間整理整理。","Por favor ordena un poco el cuarto."]]},{"id":"2-10-3","b":2,"l":10,"t":"Disposal Construction 把 bǎ with Resultative Complements","k":"disposición objeto complemento complemento resultado potencial","es":"把 + objeto + V + complemento de resultado (完, 好, 乾淨, 壞…): el objeto queda en ese estado.","ex":[["我把衣服洗乾淨了。","Lavé la ropa y quedó limpia."]]},{"id":"2-10-4","b":2,"l":10,"t":"趁 chèn seize the moment","k":"","es":"趁 + oportunidad + verbo = aprovechar el momento para…","ex":[["趁天氣好，我們去爬山吧。","Aprovechemos que hace buen tiempo para ir a la montaña."]]},{"id":"2-11-0","b":2,"l":11,"t":"The Others 其他 qítā de vs. Other 別的 biéde vs.","k":"negación negar negativa","es":"其他的 = los demás (el resto de un grupo). 別的 = otro, diferente (otra cosa u opción).","ex":[["其他的同學都走了。","Los demás compañeros ya se fueron."],["這個我不要，我要別的。","Esto no lo quiero, quiero otra cosa."]]},{"id":"2-11-1","b":2,"l":11,"t":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","k":"clasificador clasificadores medida contar cantidad","es":"Clasificadores verbales: 次 = veces; 遍 = de principio a fin; 趟 = viaje de ida y vuelta; 下 = acción breve.","ex":[["我去過兩次。","He ido dos veces."],["請你再說一遍。","Por favor dilo una vez más."]]},{"id":"2-11-2","b":2,"l":11,"t":"Expressing Next in Sequence with 然後 ránhòu, 後來 hòulái, and 以後 yǐhòu","k":"tiempo momento orden secuencia dirección movimiento","es":"然後 = luego (secuencia); 後來 = más tarde (solo para el pasado); 以後 = después (pasado o futuro).","ex":[["我先吃飯，然後看電視。","Primero como y luego veo televisión."],["後來他搬家了。","Más tarde se mudó."]]},{"id":"2-11-3","b":2,"l":11,"t":"才 cái then and only then","k":"tiempo momento orden secuencia","es":"A 才 B = solo después de A ocurre B (A es condición previa).","ex":[["吃了飯才可以玩。","Solo después de comer puedes jugar."]]},{"id":"2-11-4","b":2,"l":11,"t":"Passive Sentences with 被 bèi","k":"pasiva voz pasiva","es":"A 被 B + verbo + complemento = A es afectado por B (pasiva, suele tener sentido negativo).","ex":[["我的手機被偷了。","Me robaron el celular."]]},{"id":"2-11-5","b":2,"l":11,"t":"Verb Reduplication in V 了 le V","k":"reduplicación repetición","es":"V 了 V = hacer algo un ratito o un poco (acción ya realizada).","ex":[["我想了想，決定不去。","Lo pensé un poco y decidí no ir."]]},{"id":"2-11-6","b":2,"l":11,"t":"Verb Particle 上 shàng coming into contact","k":"","es":"V + 上 expresa contacto o cierre: 關上 (cerrar), 穿上 (ponerse), 考上 (ser admitido), 愛上 (enamorarse).","ex":[["請關上門。","Por favor cierra la puerta."],["他考上大學了。","Entró a la universidad."]]},{"id":"2-12-0","b":2,"l":12,"t":"讓 ràng to let someone do something","k":"","es":"A 讓 B + verbo = A deja / hace que B haga algo (permiso o causa).","ex":[["媽媽讓我去玩。","Mi mamá me deja ir a jugar."]]},{"id":"2-12-1","b":2,"l":12,"t":"快一點 kuài yìdiǎn hurry up","k":"","es":"快一點 = ¡date prisa! (petición o mandato suave).","ex":[["快一點，我們要遲到了。","Apúrate, vamos a llegar tarde."]]},{"id":"2-12-2","b":2,"l":12,"t":"Verb Particle 起 qǐ to touch upon","k":"","es":"V + 起 (談起, 提起, 說起, 想起) = empezar a mencionar un tema.","ex":[["他常常談起他的家人。","Habla a menudo de su familia."]]},{"id":"2-12-3","b":2,"l":12,"t":"只要 zhǐyào……就 jiù… …as long as…","k":"tiempo momento orden secuencia condicional condición si","es":"只要 A 就 B = con tal de que A, B (A es condición suficiente).","ex":[["只要你努力，就會成功。","Con tal de que te esfuerces, tendrás éxito."]]},{"id":"2-12-4","b":2,"l":12,"t":"越 yuè…越 yuè…the more…, the more…","k":"","es":"越 A 越 B = cuanto más A, más B.","ex":[["他越說越快。","Cuanto más habla, más rápido habla."]]},{"id":"2-12-5","b":2,"l":12,"t":"Topic as Contrastive","k":"","es":"Un tema al inicio sirve para contrastar con otro: «en cuanto a A…, pero B…».","ex":[["中文我會說，可是不會寫。","El chino sí sé hablarlo, pero no sé escribirlo."]]},{"id":"2-13-0","b":2,"l":13,"t":"Completion of Action with V+過 guò","k":"pasado completado terminado experiencia alguna vez haber","es":"V + 過 también indica que ya terminó de hacer algo (acción completada). Se usa sobre todo en preguntas: 吃過飯了嗎？","ex":[["你吃過飯了嗎？","¿Ya comiste?"]]},{"id":"2-13-1","b":2,"l":13,"t":"Verb Particle 走 zǒu away","k":"","es":"V + 走 = llevarse, irse (alejarse): 拿走, 帶走, 開走.","ex":[["他把我的書拿走了。","Se llevó mi libro."]]},{"id":"2-13-2","b":2,"l":13,"t":"Imperative Sentences with 叫 jiào","k":"","es":"A 叫 B + verbo = A manda o pide a B que haga algo.","ex":[["老師叫我們寫作業。","El profesor nos pide hacer la tarea."]]},{"id":"2-13-3","b":2,"l":13,"t":"別再 bié zài…了 le stop doing it","k":"negación negar negativa tiempo momento orden secuencia","es":"別再 + verbo + 了 = no lo vuelvas a hacer / deja de hacerlo.","ex":[["你別再玩手機了。","Deja de jugar con el celular."]]},{"id":"2-13-4","b":2,"l":13,"t":"To offer assurance with 會 huì…的 de…","k":"poder saber habilidad capacidad permiso posibilidad","es":"會…的 expresa seguridad o promesa sobre el futuro: «seguro que…».","ex":[["你放心，他會來的。","Tranquilo, seguro que viene."]]},{"id":"2-13-5","b":2,"l":13,"t":"透過 tòuguò… by means of…","k":"","es":"透過 + medio o persona = por medio de, a través de.","ex":[["我是透過朋友認識他的。","Lo conocí por medio de un amigo."]]},{"id":"2-13-6","b":2,"l":13,"t":"才 cái…就 jiù… only just…, and…already","k":"tiempo momento orden secuencia","es":"A 才 B 就 C = apenas A y ya B: algo ocurrió muy pronto.","ex":[["他才來一個月就學會了。","Apenas llevaba un mes y ya aprendió."]]},{"id":"2-13-7","b":2,"l":13,"t":"Frequency with 每 měi + Time Expression","k":"tiempo momento orden secuencia siempre nunca frecuencia","es":"每 + tiempo + frecuencia = tantas veces cada…","ex":[["我每個星期游泳兩次。","Nado dos veces por semana."]]},{"id":"2-13-8","b":2,"l":13,"t":"只有 zhǐyǒu…，才 cái… cannot …, unless…","k":"tiempo momento orden secuencia condicional condición si","es":"只有 A 才 B = solo si A, B (A es condición necesaria).","ex":[["只有多練習，才能說得好。","Solo practicando mucho se puede hablar bien."]]},{"id":"2-14-0","b":2,"l":14,"t":"就要 jiù yào…了 le will soon…","k":"tiempo momento orden secuencia","es":"就要 + verbo + 了 = estar a punto de. Es más cercano que 快…了.","ex":[["火車就要開了。","El tren está por salir."]]},{"id":"2-14-1","b":2,"l":14,"t":"說到 shuōdào/談到 tándào… talking of…","k":"","es":"說到 / 談到 + tema = hablando de…, cuando se trata de…","ex":[["說到台灣小吃，我最喜歡滷肉飯。","Hablando de comida callejera de Taiwán, lo que más me gusta es el lu rou fan."]]},{"id":"2-14-2","b":2,"l":14,"t":"對 duìA 有 yǒu B to be B in A","k":"","es":"對 A 有 B = hacia A hay B (efecto o sentimiento): 對…有幫助 / 有興趣 / 有信心.","ex":[["運動對身體有幫助。","Hacer ejercicio ayuda al cuerpo."]]},{"id":"2-14-3","b":2,"l":14,"t":"連 lián…都 dōu… even","k":"énfasis enfático incluso","es":"連 A 都 B = incluso A también B. A es el caso extremo.","ex":[["他連飯都沒吃就走了。","Se fue sin siquiera comer."]]},{"id":"2-14-4","b":2,"l":14,"t":"不但 búdàn…，而且 érqiě… not only…but also…","k":"negación negar negativa además adición también contraste pero sin embargo","es":"不但 A，而且 B = no solo A sino también B.","ex":[["他不但會說中文，而且說得很好。","No solo habla chino, sino que lo habla muy bien."]]},{"id":"2-14-5","b":2,"l":14,"t":"Unintentional 把 bǎ Construction","k":"disposición objeto complemento","es":"把 + objeto + verbo + complemento puede expresar algo hecho sin querer (un accidente): 弄丟, 弄壞, 忘.","ex":[["我把鑰匙弄丟了。","Perdí las llaves."]]},{"id":"2-15-0","b":2,"l":15,"t":"Post-verbal Preposition 到 dào upto, till","k":"","es":"V + 到 + tiempo / lugar = hasta (el límite de una acción).","ex":[["我昨天工作到十二點。","Ayer trabajé hasta las doce."]]},{"id":"2-15-1","b":2,"l":15,"t":"Manner 一 M 一 M one at a time","k":"","es":"一 + clasificador + 一 + clasificador = de uno en uno, poco a poco (manera).","ex":[["請大家一個一個說。","Por favor hablen uno por uno."]]},{"id":"2-15-2","b":2,"l":15,"t":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","k":"","es":"一 + clasificador + 比 + 一 + clasificador + adjetivo = cada vez más…","ex":[["天氣一天比一天冷。","Cada día hace más frío."]]},{"id":"2-15-3","b":2,"l":15,"t":"Inchoative Meaning with 起來 qǐlái","k":"dirección movimiento","es":"V / adjetivo + 起來 = empezar a (inicio de una acción o estado).","ex":[["她突然哭起來。","De pronto se puso a llorar."],["天氣冷起來了。","Empezó a hacer frío."]]},{"id":"2-15-4","b":2,"l":15,"t":"Four-character Phrases 四字格 sìzìgé","k":"","es":"Las expresiones de cuatro caracteres (四字格) condensan una idea y se usan como una unidad fija.","ex":[["這次考試我考得馬馬虎虎。","En este examen me fue así así."]]},{"id":"3-1-0","b":3,"l":1,"t":"…的話 if, supposing","k":"condicional condición si","es":"A 的話，B = si A, entonces B (condicional coloquial). Se combina con 如果 / 要是.","ex":[["如果你有空的話，我們一起去吧。","Si tienes tiempo, vamos juntos."]]},{"id":"3-1-1","b":3,"l":1,"t":"不到 less than","k":"negación negar negativa","es":"不到 + cantidad = menos de.","ex":[["我等了不到十分鐘。","Esperé menos de diez minutos."]]},{"id":"3-1-2","b":3,"l":1,"t":"差一點（就）… almost","k":"tiempo momento orden secuencia","es":"差一點(就) + verbo = por poco ocurre (pero no ocurrió).","ex":[["我差一點就遲到了。","Por poco llego tarde."]]},{"id":"3-1-3","b":3,"l":1,"t":"恐怕… probably","k":"","es":"恐怕 = me temo que, probablemente (sobre algo desfavorable).","ex":[["恐怕要下雨了。","Me temo que va a llover."]]},{"id":"3-1-4","b":3,"l":1,"t":"好不容易 finally managed to","k":"negación negar negativa","es":"好不容易 = con mucha dificultad, por fin logró.","ex":[["我好不容易才買到票。","Con mucho trabajo por fin conseguí el boleto."]]},{"id":"3-1-5","b":3,"l":1,"t":"Instantly without Prior Warning with 說…就…","k":"tiempo momento orden secuencia","es":"說 A 就 A = hacer algo en cuanto se dice, sin previo aviso.","ex":[["他說走就走。","Dijo que se iba y se fue de inmediato."]]},{"id":"3-1-6","b":3,"l":1,"t":"不管…都 … regardless of whether or not","k":"negación negar negativa","es":"不管 + pregunta u opciones，都… = no importa…, siempre…","ex":[["不管天氣好不好，他都去爬山。","Haga o no haga buen tiempo, él va a la montaña."]]},{"id":"3-2-0","b":3,"l":2,"t":"一般來說 generally speaking","k":"dirección movimiento","es":"一般來說 = en general, por lo común.","ex":[["一般來說，學生都很忙。","En general, los estudiantes están ocupados."]]},{"id":"3-2-1","b":3,"l":2,"t":"General Verb 弄","k":"","es":"弄 es un verbo comodín: «hacer, arreglar, estropear» según el complemento: 弄壞, 弄髒, 弄好.","ex":[["我把手機弄壞了。","Descompuse mi celular."]]},{"id":"3-2-2","b":3,"l":2,"t":"再說 besides, moreover","k":"tiempo momento orden secuencia además adición también","es":"再說 = además, y por si fuera poco (añade otra razón).","ex":[["太晚了，再說我也累了，明天再去吧。","Es muy tarde, además estoy cansado; vamos mañana."]]},{"id":"3-2-3","b":3,"l":2,"t":"V+成 to become, to turn into","k":"","es":"V + 成 = convertir, resultar en: 變成, 寫成, 翻成.","ex":[["請把這句話翻成中文。","Por favor traduce esta frase al chino."]]},{"id":"3-2-4","b":3,"l":2,"t":"Contrary to Expectation with 並","k":"","es":"並 + 不 / 沒 = en realidad no. Refuerza una negación contraria a lo que se esperaba.","ex":[["這件事並不難。","Este asunto en realidad no es difícil."]]},{"id":"3-2-5","b":3,"l":2,"t":"尤其是 especially","k":"","es":"尤其是 = especialmente. Destaca un caso dentro de un grupo.","ex":[["我喜歡水果，尤其是芒果。","Me gustan las frutas, sobre todo el mango."]]},{"id":"3-2-6","b":3,"l":2,"t":"Concession with 只好 could only, have no choice but to","k":"contraste pero sin embargo","es":"只好 + verbo = no queda más remedio que…","ex":[["沒有車，我們只好走路去。","No hay coche, así que no nos queda más que ir caminando."]]},{"id":"3-3-0","b":3,"l":3,"t":"受到…的影響 to be influenced by, affected by","k":"pasiva voz pasiva","es":"受到 + X + 的影響 = ser influenciado por X.","ex":[["他受到爸爸的影響，也喜歡音樂。","Influido por su papá, a él también le gusta la música."]]},{"id":"3-3-1","b":3,"l":3,"t":"幸虧… fortunately…","k":"","es":"幸虧 A，B = por suerte A, (de lo contrario habría pasado algo malo).","ex":[["幸虧你提醒我，不然我忘了。","Menos mal que me lo recordaste, si no, lo habría olvidado."]]},{"id":"3-3-2","b":3,"l":3,"t":"算是… can be considered…","k":"","es":"算是 = se puede considerar (aunque no del todo).","ex":[["這家店算是很有名的。","Esta tienda se puede considerar muy famosa."]]},{"id":"3-3-3","b":3,"l":3,"t":"是… It is indeed true that…","k":"","es":"是 acentuado antes de un adjetivo o verbo confirma algo: «sí que», «en efecto».","ex":[["他是很聰明。","Es cierto que es muy inteligente."]]},{"id":"3-3-4","b":3,"l":3,"t":"難怪 no wonder","k":"","es":"難怪 = con razón, no es de extrañar (ahora se entiende la causa).","ex":[["他是台灣人，難怪中文說得這麼好。","Es taiwanés, con razón habla tan bien chino."]]},{"id":"3-3-5","b":3,"l":3,"t":"A Post-verbal Intensifier 死了 terribly","k":"","es":"Adjetivo / verbo + 死了 = muchísimo (coloquial, para sensaciones intensas).","ex":[["我累死了。","Estoy muertísimo de cansancio."]]},{"id":"3-3-6","b":3,"l":3,"t":"幾乎 almost","k":"","es":"幾乎 = casi (casi todo, casi siempre, casi ocurre).","ex":[["他幾乎每天都來。","Viene casi todos los días."]]},{"id":"3-3-7","b":3,"l":3,"t":"多少 somewhat","k":"","es":"多少 + verbo / adjetivo = en alguna medida, algo, aunque sea un poco.","ex":[["他多少知道一點。","Algo sabe, aunque sea un poco."]]},{"id":"3-3-8","b":3,"l":3,"t":"再…也… no matter how…, still…","k":"tiempo momento orden secuencia","es":"再 + adjetivo / verbo + 也 = por más… que sea, aun así…","ex":[["再忙我也要吃早餐。","Por muy ocupado que esté, desayuno."]]},{"id":"3-4-0","b":3,"l":4,"t":"不但…，還… not only…, but also","k":"negación negar negativa además adición también contraste pero sin embargo","es":"不但 A，還 B = no solo A, también B.","ex":[["他不但會唱歌，還會跳舞。","No solo canta, también baila."]]},{"id":"3-4-1","b":3,"l":4,"t":"Speak 說 vs Talk 談","k":"","es":"說 = decir o hablar (producir palabras). 談 = conversar o discutir un tema con intercambio.","ex":[["他說中文。","Habla chino."],["我們談一談這個問題。","Hablemos de este problema."]]},{"id":"3-4-2","b":3,"l":4,"t":"…不是…，而是… not…; rather…","k":"negación negar negativa contraste pero sin embargo","es":"不是 A，而是 B = no es A, sino B.","ex":[["他不是不想去，而是沒時間。","No es que no quiera ir, es que no tiene tiempo."]]},{"id":"3-4-3","b":3,"l":4,"t":"從來+Negation never","k":"negación negar negativa lugar ubicación dónde existencia hay dirección movimiento siempre nunca frecuencia","es":"從來 + 不 / 沒 (有) = nunca, jamás (hasta ahora).","ex":[["我從來沒吃過榴槤。","Nunca he comido durián."]]},{"id":"3-4-4","b":3,"l":4,"t":"Various Meanings of the Verb 上","k":"","es":"上 tiene varios sentidos como verbo: 上課, 上班, 上網, 上車 (empezar o ir a una actividad, subir).","ex":[["他每天坐捷運上班。","Va al trabajo en metro todos los días."]]},{"id":"3-4-5","b":3,"l":4,"t":"非…不可 it is imperative that…","k":"negación negar negativa","es":"非 A 不可 = es imprescindible A, tiene que ser A.","ex":[["明天的會，你非來不可。","A la reunión de mañana tienes que venir sí o sí."]]},{"id":"3-4-6","b":3,"l":4,"t":"對…來說 as far as...is concerned, for","k":"dirección movimiento","es":"對 X 來說 = para X, desde la perspectiva de X.","ex":[["對學生來說，睡眠很重要。","Para los estudiantes, dormir es muy importante."]]},{"id":"3-4-7","b":3,"l":4,"t":"對…講究 to be discerning, discriminating, particular about","k":"","es":"對 X 很講究 = ser exigente o cuidadoso con X.","ex":[["他對吃很講究。","Es muy exigente con la comida."]]},{"id":"3-5-0","b":3,"l":5,"t":"Verb Plus Complement V+滿 crowded with","k":"complemento resultado potencial","es":"V + 滿 = llenar: el espacio queda lleno.","ex":[["教室裡坐滿了人。","El salón está lleno de gente sentada."]]},{"id":"3-5-1","b":3,"l":5,"t":"Verb Particle 出 to have emerged","k":"","es":"V + 出 (來) = salir o aparecer; también descubrir o distinguir: 想出, 做出, 看出.","ex":[["我看不出他是外國人。","No me doy cuenta de que sea extranjero."]]},{"id":"3-5-2","b":3,"l":5,"t":"不如 not as good as","k":"comparar comparación comparativo más menos igual semejante negación negar negativa","es":"A 不如 B = A no es tan bueno como B (B es mejor).","ex":[["坐車不如坐捷運方便。","Ir en coche no es tan cómodo como ir en metro."]]},{"id":"3-5-3","b":3,"l":5,"t":"Urgent Conditional with 再不…就…了","k":"negación negar negativa tiempo momento orden secuencia condicional condición si","es":"再不 A 就 B 了 = si no hacemos A ya, ocurrirá B (urgencia).","ex":[["再不走，就來不及了。","Si no nos vamos ya, no llegamos."]]},{"id":"3-5-4","b":3,"l":5,"t":"Verb Particle 掉 separated from","k":"","es":"V + 掉 = quitar, eliminar o perder: 丟掉, 吃掉, 忘掉.","ex":[["請把垃圾丟掉。","Por favor tira la basura."]]},{"id":"3-5-5","b":3,"l":5,"t":"居然 to one’s surprise","k":"énfasis enfático incluso","es":"居然 = increíblemente, ¡quién lo diría! (sorpresa).","ex":[["他居然忘了今天考試。","¡Increíble, se olvidó del examen de hoy!"]]},{"id":"3-5-6","b":3,"l":5,"t":"Concession with 既然…（就）… since…(then)…","k":"tiempo momento orden secuencia condicional condición si","es":"既然 A (就) B = ya que A, entonces B (A es un hecho aceptado).","ex":[["既然你累了，就早點休息吧。","Ya que estás cansado, descansa temprano."]]},{"id":"3-5-7","b":3,"l":5,"t":"V+個不停 keep on…","k":"negación negar negativa","es":"V + 個不停 = no parar de hacer algo.","ex":[["孩子哭個不停。","El niño no deja de llorar."]]},{"id":"3-6-0","b":3,"l":6,"t":"因為…才… only because…","k":"tiempo momento orden secuencia causa razón porque consecuencia resultado","es":"因為 A 才 B = justamente por A es que B.","ex":[["就是因為你幫我，我才成功。","Fue justo porque tú me ayudaste que tuve éxito."]]},{"id":"3-6-1","b":3,"l":6,"t":"Complaining with …S1…不說，S2 也… not merely, but also","k":"negación negar negativa contraste pero sin embargo","es":"S1 … 不說，S2 也… = no solo S1, además S2 (para quejarse de algo que se suma).","ex":[["他遲到不說，也不道歉。","Llegó tarde y encima no pidió disculpas."]]},{"id":"3-6-2","b":3,"l":6,"t":"再加上 furthermore","k":"tiempo momento orden secuencia además adición también","es":"再加上 = sumado a, además. Añade otra razón.","ex":[["天氣冷，再加上下雨，我不想出門。","Hace frío y además llueve, no quiero salir."]]},{"id":"3-6-3","b":3,"l":6,"t":"什麼都…，就是… everything but …","k":"tiempo momento orden secuencia contraste pero sin embargo","es":"什麼都 A，就是 B = de todo A, pero no B.","ex":[["我什麼都吃，就是不吃香菜。","Como de todo, menos cilantro."]]},{"id":"3-6-4","b":3,"l":6,"t":"寧可…也要… would rather…, in order to…","k":"","es":"寧可 A 也要 B = preferir A antes que renunciar a B (sacrificio).","ex":[["他寧可不睡覺也要把書看完。","Prefiere no dormir con tal de terminar el libro."]]},{"id":"3-6-5","b":3,"l":6,"t":"像…的+noun such (nouns) as","k":"comparar comparación comparativo más menos igual semejante","es":"像 X 的 N = N como X (da ejemplos de una categoría).","ex":[["像芒果、西瓜的水果，我都喜歡。","Frutas como el mango y la sandía, me gustan todas."]]},{"id":"3-6-6","b":3,"l":6,"t":"一方面…，一方面… on the one hand, …, on the other","k":"","es":"一方面 A，一方面 B = por un lado A, por otro lado B.","ex":[["一方面要工作，一方面要念書，很累。","Por un lado trabajar y por otro estudiar, es agotador."]]},{"id":"3-6-7","b":3,"l":6,"t":"隨著 S1…，S2 也… as a consequence of…","k":"progresivo continuo estar haciendo presente","es":"隨著 X，Y 也… = a medida que X, Y también…","ex":[["隨著年紀增加，他的想法也不一樣了。","A medida que crece, sus ideas también cambian."]]},{"id":"3-7-0","b":3,"l":7,"t":"亂＋V to do something in an irresponsible manner,","k":"","es":"亂 + verbo = hacer algo sin orden ni cuidado.","ex":[["不要亂丟垃圾。","No tires basura por cualquier lado."]]},{"id":"3-7-1","b":3,"l":7,"t":"各 V 各的 each doing her/his own…","k":"","es":"各 V 各的 = cada uno hace lo suyo.","ex":[["吃飯的時候，大家各玩各的手機。","Mientras comen, cada uno juega con su celular."]]},{"id":"3-7-2","b":3,"l":7,"t":"就算…，也… even if…(S1) …, would…(S2)…","k":"tiempo momento orden secuencia condicional condición si","es":"就算 A，也 B = aunque A (hipótesis), igual B.","ex":[["就算下雨，我也要去。","Aunque llueva, voy a ir."]]},{"id":"3-7-3","b":3,"l":7,"t":"因為 NP，S… because of NP, S…","k":"causa razón porque consecuencia resultado","es":"因為 + sustantivo，S… = debido a + sustantivo.","ex":[["因為天氣，比賽取消了。","Por el clima, se canceló el partido."]]},{"id":"3-7-4","b":3,"l":7,"t":"一來…，二來… on the one hand…, and on the other…; first…, second…","k":"dirección movimiento","es":"一來 A，二來 B = primero A, segundo B (enumera razones).","ex":[["我不去，一來太遠，二來沒時間。","No voy: primero, está muy lejos; segundo, no tengo tiempo."]]},{"id":"3-7-5","b":3,"l":7,"t":"Repetitively, Back and Forth with V 來 V 去","k":"dirección movimiento","es":"V 來 V 去 = hacer algo de aquí para allá o una y otra vez.","ex":[["他走來走去。","Camina de un lado a otro."],["我想來想去，還是不去。","Lo pensé y lo pensé, y al final decidí no ir."]]},{"id":"3-7-6","b":3,"l":7,"t":"不再…了 not…any more","k":"negación negar negativa tiempo momento orden secuencia","es":"不再 + verbo + 了 = ya no (algo que antes sí se hacía).","ex":[["他不再喝咖啡了。","Ya no toma café."]]},{"id":"3-8-0","b":3,"l":8,"t":"不是…就是… if it's not…, then it’s…","k":"negación negar negativa tiempo momento orden secuencia","es":"不是 A 就是 B = o bien A o bien B.","ex":[["他週末不是看書就是睡覺。","Los fines de semana o lee o duerme."]]},{"id":"3-8-1","b":3,"l":8,"t":"算了 forget it, drop it","k":"","es":"算了 = déjalo, olvídalo (dejar pasar o renunciar).","ex":[["太貴了，算了。","Es muy caro, mejor olvídalo."]]},{"id":"3-8-2","b":3,"l":8,"t":"這樣一來 that being the case, that way","k":"dirección movimiento","es":"這樣一來 = de esta manera, en ese caso (introduce la consecuencia).","ex":[["這樣一來，我們就不用等了。","Así ya no tenemos que esperar."]]},{"id":"3-8-3","b":3,"l":8,"t":"早就…了 long since…","k":"tiempo momento orden secuencia","es":"早就 + verbo + 了 = hace mucho que ya…","ex":[["我早就知道了。","Hace tiempo que lo sé."]]},{"id":"3-8-4","b":3,"l":8,"t":"從…起 starting from…","k":"lugar ubicación dónde existencia hay","es":"從 + tiempo / lugar + 起 = a partir de.","ex":[["從明天起，我要早起。","A partir de mañana voy a madrugar."]]},{"id":"3-8-5","b":3,"l":8,"t":"卻 however","k":"contraste pero sin embargo","es":"卻 = sin embargo, en cambio (contraste inesperado). Va antes del verbo.","ex":[["他很聰明，卻不愛念書。","Es muy inteligente, pero no le gusta estudiar."]]},{"id":"3-8-6","b":3,"l":8,"t":"因為…而… therefore, consequently","k":"causa razón porque consecuencia resultado","es":"因為 X 而 V = por X, (resulta) V. Es una forma más escrita.","ex":[["他因為生病而沒來上課。","No vino a clase porque se enfermó."]]},{"id":"3-8-7","b":3,"l":8,"t":"經過 after","k":"","es":"經過 = pasar por (un lugar) o tras (un proceso o tiempo).","ex":[["經過一年的努力，他通過了考試。","Tras un año de esfuerzo, aprobó el examen."]]},{"id":"3-9-0","b":3,"l":9,"t":"靠 to rely on, by means of","k":"","es":"靠 = depender de, apoyarse en.","ex":[["他靠自己的努力考上大學。","Entró a la universidad gracias a su propio esfuerzo."]]},{"id":"3-9-1","b":3,"l":9,"t":"既…又… not merely…, but…as well","k":"contraste pero sin embargo","es":"既 A 又 B = tanto A como B (dos cualidades; más formal que 又…又…).","ex":[["這裡既安靜又乾淨。","Este lugar es tranquilo y limpio."]]},{"id":"3-9-2","b":3,"l":9,"t":"…以內 within …","k":"","es":"以內 = dentro de (un límite de cantidad, tiempo o espacio).","ex":[["請在三天以內回覆。","Por favor responde en un plazo de tres días."]]},{"id":"3-9-3","b":3,"l":9,"t":"占 to constitute","k":"","es":"占 = ocupar o representar (una parte o porcentaje).","ex":[["女生占全班的一半。","Las mujeres son la mitad de la clase."]]},{"id":"3-9-4","b":3,"l":9,"t":"（在） NP 上 regarding NP","k":"","es":"(在) N 上 = en el aspecto de N, en cuanto a N.","ex":[["在學習上，他很認真。","En los estudios, él es muy aplicado."]]},{"id":"3-9-5","b":3,"l":9,"t":"給…帶來 to bring… to…","k":"dirección movimiento","es":"給 A 帶來 B = traerle B a A (efecto o consecuencia).","ex":[["網路給我們帶來很多方便。","Internet nos trae muchas comodidades."]]},{"id":"3-9-6","b":3,"l":9,"t":"結果 consequently, in the end","k":"causa razón porque consecuencia resultado","es":"結果 = el resultado fue…, al final (el desenlace de algo).","ex":[["我等了很久，結果他沒來。","Esperé mucho y al final no vino."]]},{"id":"3-10-0","b":3,"l":10,"t":"Introducing a New Topic with 至於…, as to, as far","k":"","es":"至於 = en cuanto a… (cambia a otro tema).","ex":[["我去，至於他去不去，我不知道。","Yo voy; en cuanto a si él va o no, no lo sé."]]},{"id":"3-10-1","b":3,"l":10,"t":"看 depends on","k":"","es":"A 看 B = A depende de B.","ex":[["去不去看天氣。","Ir o no depende del clima."]]},{"id":"3-10-2","b":3,"l":10,"t":"一向 all along, has always…","k":"siempre nunca frecuencia","es":"一向 = siempre (desde antes hasta ahora, como hábito).","ex":[["他一向早起。","Siempre se ha levantado temprano."]]},{"id":"3-10-3","b":3,"l":10,"t":"拿…來說 take…as an example","k":"dirección movimiento","es":"拿 X 來說 = tomando X como ejemplo.","ex":[["拿我自己來說，我就不喜歡吃辣。","Por ejemplo, yo no como picante."]]},{"id":"3-10-4","b":3,"l":10,"t":"Passive Sentences with 受","k":"pasiva voz pasiva","es":"受 + sustantivo: 受到歡迎 (ser bien recibido), 受傷 (herirse), 受影響 (ser afectado). Pasiva de estilo más formal.","ex":[["這部電影很受歡迎。","Esta película es muy popular."]]},{"id":"3-10-5","b":3,"l":10,"t":"動不動就… to do something impetuously","k":"negación negar negativa tiempo momento orden secuencia","es":"動不動就 + verbo = a la menor ocasión, por cualquier cosa (negativo).","ex":[["他動不動就生氣。","Se enoja por cualquier cosa."]]},{"id":"3-11-0","b":3,"l":11,"t":"到底 after all? how on earth…?","k":"pregunta preguntar interrogativa","es":"到底 = en realidad, ¿qué demonios…? Insiste en una pregunta.","ex":[["你到底想吃什麼？","¿Pero qué quieres comer en realidad?"]]},{"id":"3-11-1","b":3,"l":11,"t":"甚至 even","k":"énfasis enfático incluso","es":"甚至 = incluso, hasta (el caso extremo).","ex":[["他很忙，甚至沒有時間吃飯。","Está muy ocupado, incluso no tiene tiempo para comer."]]},{"id":"3-11-2","b":3,"l":11,"t":"這麼說 that being the case, in that case","k":"","es":"這麼說 = entonces, siendo así… (se concluye a partir de lo que dijo el otro).","ex":[["這麼說，你已經知道了？","Entonces, ¿ya lo sabías?"]]},{"id":"3-11-3","b":3,"l":11,"t":"跟 B 有關的 A A is related to B","k":"","es":"跟 B 有關的 A = A relacionado con B.","ex":[["我想看跟台灣歷史有關的書。","Quiero leer libros sobre la historia de Taiwán."]]},{"id":"3-11-4","b":3,"l":11,"t":"不得不 have no choice but to","k":"negación negar negativa complemento resultado potencial contraste pero sin embargo","es":"不得不 + verbo = no tener más remedio que, verse obligado a.","ex":[["太晚了，我不得不回家。","Es muy tarde, no tengo más remedio que irme a casa."]]},{"id":"3-11-5","b":3,"l":11,"t":"以及 as well as","k":"","es":"以及 = así como. Une sustantivos (más formal).","ex":[["我買了蘋果、香蕉以及芒果。","Compré manzanas, plátanos y mangos."]]},{"id":"3-12-0","b":3,"l":12,"t":"只不過… (而已) merely…; nothing more than…","k":"negación negar negativa","es":"只不過…(而已) = simplemente, no es más que…","ex":[["這只不過是一個小問題而已。","Esto no es más que un pequeño problema."]]},{"id":"3-12-1","b":3,"l":12,"t":"Introducing an Agent with 由","k":"","es":"由 + agente + verbo = a cargo de, por parte de (quien hace algo).","ex":[["這件事由我來做。","De esto me encargo yo."]]},{"id":"3-12-2","b":3,"l":12,"t":"難道… how could it possibly be true","k":"pregunta preguntar interrogativa","es":"難道…嗎？ = ¿acaso…? Pregunta retórica.","ex":[["難道你不知道嗎？","¿Acaso no lo sabías?"]]},{"id":"3-12-3","b":3,"l":12,"t":"To Reach a Ceiling with 滿","k":"","es":"滿 = llegar al máximo, estar lleno: 客滿, 額滿, 坐滿.","ex":[["今天餐廳客滿了。","Hoy el restaurante está lleno."]]},{"id":"3-12-4","b":3,"l":12,"t":"Beneficiary marker 為","k":"","es":"為 + beneficiario + verbo = por / para (a favor de).","ex":[["他為家人工作。","Trabaja por su familia."]]},{"id":"3-12-5","b":3,"l":12,"t":"（在）…方面 with respect to; regarding","k":"","es":"(在) X 方面 = en el aspecto de X, con respecto a X.","ex":[["在工作方面，他很努力。","En lo laboral, se esfuerza mucho."]]}]};
